import{_ as n,H as e,f as s,i as t}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"08｜使用AutoGPT实现Autonomous Agent应用","description":"","frontmatter":{},"headers":[{"level":2,"title":"角色建模和工作流设计","slug":"角色建模和工作流设计","link":"#角色建模和工作流设计","children":[]},{"level":2,"title":"逢山开路，遇水架桥——解决应用实现时遇到的挑战","slug":"逢山开路-遇水架桥——解决应用实现时遇到的挑战","link":"#逢山开路-遇水架桥——解决应用实现时遇到的挑战","children":[]},{"level":2,"title":"实现并测试 GameDealer","slug":"实现并测试-gamedealer","link":"#实现并测试-gamedealer","children":[]},{"level":2,"title":"实现并测试 MathProdigy","slug":"实现并测试-mathprodigy","link":"#实现并测试-mathprodigy","children":[]},{"level":2,"title":"实现并测试 GameJudger","slug":"实现并测试-gamejudger","link":"#实现并测试-gamejudger","children":[]},{"level":2,"title":"实现并测试 GamePlayer","slug":"实现并测试-gameplayer","link":"#实现并测试-gameplayer","children":[]},{"level":2,"title":"实现并测试完整的游戏工作流","slug":"实现并测试完整的游戏工作流","link":"#实现并测试完整的游戏工作流","children":[]},{"level":2,"title":"总结时刻","slug":"总结时刻","link":"#总结时刻","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"LLM自主智能体应用实战课/08｜使用AutoGPT实现AutonomousAgent应用.md","filePath":"LLM自主智能体应用实战课/08｜使用AutoGPT实现AutonomousAgent应用.md","lastUpdated":1779815961000}'),p={name:"LLM自主智能体应用实战课/08｜使用AutoGPT实现AutonomousAgent应用.md"};function l(o,a,i,r,c,u){return e(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="_08-使用autogpt实现autonomous-agent应用" tabindex="-1">08｜使用AutoGPT实现Autonomous Agent应用 <a class="header-anchor" href="#_08-使用autogpt实现autonomous-agent应用" aria-label="Permalink to &quot;08｜使用AutoGPT实现Autonomous Agent应用&quot;">​</a></h1><p>你好，我是李锟。</p><p>在前面两节课中，我们花费了不少工夫安装好 AutoGPT，熟悉了 AutoGPT 的工作和开发模式，并且解决了开发 AutoGPT 应用的两个直接挑战。这节课将开启一个非常有意思的部分，开发我们自己的第一个 Autonomous Agent 应用（为了吃这碟醋，我们来包一顿饺子）。我会带着你基于 AutoGPT 实现 <a href="https://time.geekbang.org/column/article/838710" target="_blank" rel="noreferrer">01 课</a> 中讨论过的那个 24 点游戏智能体应用。</p><h2 id="角色建模和工作流设计" tabindex="-1">角色建模和工作流设计 <a class="header-anchor" href="#角色建模和工作流设计" aria-label="Permalink to &quot;角色建模和工作流设计&quot;">​</a></h2><p>与 <a href="https://time.geekbang.org/column/article/840305" target="_blank" rel="noreferrer">04 课</a> 的设计开发过程相同，我们要做的第一步仍然是角色和工作流设计。因为我们在 04 课中已经基于 MetaGPT 实现过一次这个应用，很熟悉这个应用中的角色和工作流。不需要重复相同的内容，在这节课里我们要做的是把 04 课针对 MetaGPT 的设计和实现移植到 AutoGPT 的环境。</p><p>从 <a href="https://time.geekbang.org/column/article/841091" target="_blank" rel="noreferrer">06 课</a> 中学习到的 AutoGPT 基础概念，我们理解了 MetaGPT 的 Action 对应 AutoGPT 的 Block，因此 Action 可以直接移植为 Block。那么 MetaGPT 的 Role 在 AutoGPT 中对应的是什么呢？在 AutoGPT 中，与 Role 对应的概念就是 Agent。MetaGPT 支持多个 Role 的协作，同样的，AutoGPT 新版本也支持多个 Agent 的协作 (老版本仅支持单个 Agent)。</p><p>关于 AutoGPT 新版本中的多 Agent 协作，因为代码才实现不久，官方文档严重滞后，甚至没有说这件事。好在其开发团队还有一个 <a href="https://agpt.co/blog" target="_blank" rel="noreferrer">官方 blog 网站</a>，他们在 2024年11月22日的一篇 blog： <a href="https://agpt.co/blog/introducing-agent-blocks" target="_blank" rel="noreferrer">Introducing Agent Blocks: Build AI Workflows That Scale Through Multi-Agent Collaboration</a> 中说了这件事。</p><p>更早之前在2024年7月，创始人 Toran Bruce Richards 发布在 X (即 Twitter) 上的文章 <a href="https://x.com/SigGravitas/status/1812803289739633018" target="_blank" rel="noreferrer">Introducing the Next Generation of</a> <a href="https://x.com/SigGravitas/status/1812803289739633018" target="_blank" rel="noreferrer">AutoGPT</a> 介绍了新版本的 AutoGPT。根据 Toran 的这篇文章以及他对留言的回复，AutoGPT 新版本的一个重要目标，就是能够很好地支持多 Agent 的协作。国内的技术媒体机器之心对 Toran 的这篇文章有及时的报道： <a href="https://mp.weixin.qq.com/s/dBL47yYoVNkyPoPG8pcLLA" target="_blank" rel="noreferrer">GitHub 星标超 16 万，爆火 AutoGPT 进阶版来了：定制节点、多智能体协同</a>。</p><p>既然 AutoGPT 新版本的 Agent 对应着 MetaGPT 的 Role，貌似 04 课中的工作流不需要做任何修改。然而经过我的测试，AutoGPT 新版本现有代码不是很稳定，每个 Agent 如果有两个输入，工作流在运行时会卡住。</p><p>在 24 点游戏应用的这个例子中具体来说就是 GameJudger 有两个输入 (承担了两个职责)：发牌和验证表达式是否正确。解决方法其实不难，可以把发牌的职责从 GameJudger 中分出来，单独创建一个 GameDealer (游戏发牌员)，这样每个 GameJudger 就只有一个输入了。按照新的角色划分方式，我对 04 课中的流程图做了修改，新的流程图如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/842359/19fdb17bc3d8cf5842b2b57187ac1c25.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/842359/19fdb17bc3d8cf5842b2b57187ac1c25.png" alt=""></a></p><p>既然实现思路确定了，是不是就会一切顺利了呢？很遗憾，并非如此。</p><p>因为 AutoGPT 新版本正处于快速发展过程中，相关的文档极为欠缺。对于初学者来说，学习 AutoGPT 新版本可谓是障碍重重。我们必须采取不断探索的方式，通过解决实现过程中遇到的挑战来进行学习。很重要的是与 AutoGPT 开发团队保持密切的沟通，AutoGPT 开发团队的成员 (包括 Toran 在内) 大多都非常友善，可以直接与他们取得联系，向他们求教。</p><p>与 AutoGPT 开发团队最直接的联系方式是通过 <a href="https://discord.gg/autogpt" target="_blank" rel="noreferrer">Discord</a>，此外还可以向 AutoGPT 的 GitHub 项目直接提交 issue。</p><h2 id="逢山开路-遇水架桥——解决应用实现时遇到的挑战" tabindex="-1">逢山开路，遇水架桥——解决应用实现时遇到的挑战 <a class="header-anchor" href="#逢山开路-遇水架桥——解决应用实现时遇到的挑战" aria-label="Permalink to &quot;逢山开路，遇水架桥——解决应用实现时遇到的挑战&quot;">​</a></h2><p>我们需要先解决一些实现 24 点游戏应用过程中遇到的挑战，然后才能顺利将这个应用移植到 AutoGPT。学以致用极为重要，如果我们不从应用的需求出发亲自动手，就不会遇到这些挑战。</p><p><strong>我们遇到的第一个挑战是：如何将 AutoGPT 的 Agent 实现为人类用户，即可接受人类用户的输入。</strong></p><p>在 04 课的 MetaGPT 应用中，GamePlayer 这个 Role 是人类用户，因此在 AutoGPT 中，对应的 GamePlayer 这个 Agent 也应该是人类用户。在 04 课的实现中，接受人类用户输入的 Action 是 GetHumanReply，因此我在 AutoGPT 中建造了一个对应的 GetHumanReplyBlock，希望在这个 Block 的实现中接受用户的输入。然而尝试了一段时间，并且在 Discord 群里向 AutoGPT 开发团队成员求助，我发现目前这个功能是无法实现的。</p><p>在 AutoGPT 的 <a href="https://docs.agpt.co/platform/blocks/blocks/" target="_blank" rel="noreferrer">官方 Blocks 列表</a> 中我发现有一个现成的 <a href="https://docs.agpt.co/platform/blocks/basic/#agent-input" target="_blank" rel="noreferrer">Agent Input Block</a>，做的事情就是接受用户的输入。我想这下子省事了，直接使用这个 AgentInputBlock 就好了，不需要自己实现 GetHumanReplyBlock。</p><p>很快我就发现了一个严重问题，现有版本的 AgentInputBlock 只支持在整个工作流运行之前输入内容，而不是在工作流运行过程的中间节点输入内容。这样就不符合我们的要求了，因为 GamePlayer 输入内容是在他收到 GameDealer 发的牌之后。我与 AutoGPT 开发团队成员讨论过这个需求 (支持工作流中间节点的用户输入)，他们承诺会尽快解决这个问题。</p><p>预计在本课程上线时，这个问题已经得到解决，到那个时候我会及时更新本节课的内容。本节课目前的内容是过渡性的，我们需要找到一个临时解决方案，绕开这个问题。一个绕开这个问题的方法是模仿用户的输入，在 GamePlayer 的所有允许的选项中，每次随机选择其中一种。</p><p>在 GetHumanReplyBlock 当前的过渡实现中，run() 函数是这样的：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    def run(self, input_data: Input, **kwargs) -&amp;gt; BlockOutput:</span></span>
<span class="line"><span>        cards_posted = input_data.cards_posted</span></span>
<span class="line"><span>        input_list = [</span></span>
<span class="line"><span>            &quot;deal&quot;,</span></span>
<span class="line"><span>            &quot;help&quot;,</span></span>
<span class="line"><span>            &quot;exit&quot;,</span></span>
<span class="line"><span>            &quot;12 + 2 * (1 + 5)&quot;,</span></span>
<span class="line"><span>            &quot;5 * 3 - 7 + 11&quot;,</span></span>
<span class="line"><span>        ]</span></span>
<span class="line"><span>        input_idx = random.randint(0, 4)</span></span>
<span class="line"><span>        yield &quot;user_input&quot;, input_list[input_idx]</span></span></code></pre></div><p>GamePlayer 一共有 4 种允许的选项：</p><ul><li><p>输入 “deal” 请求 GameDealer 重新发牌</p></li><li><p>输入 “help” 请求 MathProdigy 协助给出正确的 24 点表达式</p></li><li><p>输入 “exit” 请求退出游戏</p></li><li><p>输入一个 24 点表达式（正确、错误的表达式各一种）</p></li></ul><p>在上述代码中，GetHumanReplyBlock 会随机返回 4 种选项中的一种（具体实现中是 5 种，因为 24 点表达式还分成正确、错误两种）。</p><p>注意：为了简化教学起见，GameJudger 的实现中并未检查 GamePlayer 给出的 24 点表达式中的 4 个整数是否与 GameDealer 最近发的牌一致，而只是简单检查了 24 点表达式的结果是否正确。检查 24 点表达式中的 4 个整数是否与发的牌一致，我将这个任务留给你在课后自行实现。</p><p><strong>第二个挑战是搞清楚在 AutoGPT 中如何根据不同的情况调用不同的 Block，而不是只能串行工作。</strong></p><p>我们需要有一个能够执行条件判断的 Block，以便实现工作流中的不同分支，类似编程语言之中的 if…elif…else 这样的结构。查找 <a href="https://docs.agpt.co/platform/blocks/blocks/" target="_blank" rel="noreferrer">官方 Blocks 列表</a> 我发现有一个 <a href="https://docs.agpt.co/platform/blocks/branching/#condition-block" target="_blank" rel="noreferrer">Condition Block</a>，就是来做条件判断的。OK，我们尝试使用这个 ConditionBlock 来实现条件判断，而不是自己发明轮子。</p><p><strong>第三个挑战是搞清楚在 AutoGPT 的 Block 中如何与 LLM 交互。</strong></p><p>在 <a href="https://docs.agpt.co/platform/blocks/blocks/" target="_blank" rel="noreferrer">官方 Blocks 列表</a> 中有一个 <a href="https://docs.agpt.co/platform/blocks/llm/#ai-conversation" target="_blank" rel="noreferrer">AI Conversation Block</a>，在上节课中我已经展示了它的用法，这个 Block 可以用来实现与 LLM 的一次对话。然而试用了这个 AIConversationBlock 之后，我发现它的输入格式无法满足 24 点游戏应用的需要。</p><p>具体来说，发牌和验证表达式是否正确，这两个 Block 需要的输入格式与 AIConversationBlock 是不同的，无法直接使用 AIConversationBlock。因此我选择了实现两个 AIConversationBlock 的子类 DealCardsBlock 和 CheckExpressionBlock，对应 04 课 <a href="https://gitee.com/mozilla88/autonomous_agent/blob/master/lesson_04/play_24_points_game_v2.py" target="_blank" rel="noreferrer">play_24_points_game_v2.py</a> 中的 DealCards 和 CheckExpression 这两个 Action。</p><p>还有一件事我们在上节课中忘记做了，除了 qwen2.5 外，还需要支持 qwen2.5-math。解决方法与上节课的方法类似，只需要修改两个文件：autogpt_platform/backend/backend/blocks/llm.py 和 autogpt_platform/backend/backend/data/block_cost_config.py。</p><p>我们在 llm.py 中添加两行。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Ollama models</span></span>
<span class="line"><span>OLLAMA_LLAMA3_8B = &quot;llama3&quot;</span></span>
<span class="line"><span>OLLAMA_LLAMA3_405B = &quot;llama3.1:405b&quot;</span></span>
<span class="line"><span>OLLAMA_QWEN2_5_7B = &quot;qwen2.5&quot;</span></span>
<span class="line"><span>OLLAMA_QWEN2_5_MATH_7B = &quot;qwen2.5-math&quot;  # 新增内容</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Limited to 16k during preview</span></span>
<span class="line"><span>LlmModel.LLAMA3_1_70B: ModelMetadata(&quot;groq&quot;, 131072),</span></span>
<span class="line"><span>LlmModel.LLAMA3_1_8B: ModelMetadata(&quot;groq&quot;, 131072),</span></span>
<span class="line"><span>LlmModel.OLLAMA_LLAMA3_8B: ModelMetadata(&quot;ollama&quot;, 8192),</span></span>
<span class="line"><span>LlmModel.OLLAMA_LLAMA3_405B: ModelMetadata(&quot;ollama&quot;, 8192),</span></span>
<span class="line"><span>LlmModel.OLLAMA_QWEN2_5_7B: ModelMetadata(&quot;ollama&quot;, 8192),</span></span>
<span class="line"><span>LlmModel.OLLAMA_QWEN2_5_MATH_7B: ModelMetadata(&quot;ollama&quot;, 8192),  # 新增内容</span></span></code></pre></div><p>在 block_cost_config.py 中添加一行。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LlmModel.OLLAMA_LLAMA3_8B: 1,</span></span>
<span class="line"><span>LlmModel.OLLAMA_LLAMA3_405B: 1,</span></span>
<span class="line"><span>LlmModel.OLLAMA_QWEN2_5_7B: 1,</span></span>
<span class="line"><span>LlmModel.OLLAMA_QWEN2_5_MATH_7B: 1,  # 新增内容</span></span></code></pre></div><p><strong>第四个挑战是搞清楚如何把多个 Agent 连接起来。</strong></p><p>通过阅读 AutoGPT 的官方文档，我们判断出实现这个目标的就是 AgentInputBlock 和 AgentOutputBlock 这两个 Block。在 04 课的 MetaGPT 实现中，CallMathProdigy、WrongExpression、RequireDealCardsAgain、ExitGame 这几个不需要业务逻辑，仅仅作为事件信息载体的 Action，在 AutoGPT 中都可以使用 AgentOutputBlock 来实现。</p><p>解决了上述这四个挑战之后，我们就可以分别来实现并测试流程图中的 4 个 Agent 了。我们按照从简单到复杂的顺序来分别实现。</p><h2 id="实现并测试-gamedealer" tabindex="-1">实现并测试 GameDealer <a class="header-anchor" href="#实现并测试-gamedealer" aria-label="Permalink to &quot;实现并测试 GameDealer&quot;">​</a></h2><p>对于 AutoGPT 中的每个 Agent，其实现都包括了两部分：</p><ol><li><p>以 Python 代码形式实现的自定义 Block。</p></li><li><p>在 AutoGPT Frontend 的图形界面中，基于 AutoGPT 官方 Block + 自定义 Block 实现 Agent 的工作流。工作流实现和相关配置会保存在 AutoGPT Server 的 PostgreSQL 数据库中。</p></li></ol><p>在 GameDealer 这个 Agent 中，我们需要移植 MetaGPT 实现中的 DealCards。我创建了一个对应的 DealCardsBlock，这个类是 AIConversationBlock 的子类。在这里我只展示其 run() 函数的实现。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    def run(</span></span>
<span class="line"><span>        self, input_data: Input, *, credentials: APIKeyCredentials, **kwargs</span></span>
<span class="line"><span>    ) -&amp;gt; BlockOutput:</span></span>
<span class="line"><span>        old_cards_arrays = get_old_cards_arrays()</span></span>
<span class="line"><span>        logger.info(f&quot;used old_arrays is :{old_cards_arrays}&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        prompt = self.PROMPT_TEMPLATE.format(old_arrays=old_cards_arrays)</span></span>
<span class="line"><span>        msg_list = [ {&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: prompt} ]</span></span>
<span class="line"><span>        rsp = self.llm_call(</span></span>
<span class="line"><span>            AIStructuredResponseGeneratorBlock.Input(</span></span>
<span class="line"><span>                prompt=&quot;&quot;,</span></span>
<span class="line"><span>                credentials=input_data.credentials,</span></span>
<span class="line"><span>                model=input_data.model,</span></span>
<span class="line"><span>                conversation_history=msg_list,</span></span>
<span class="line"><span>                max_tokens=input_data.max_tokens,</span></span>
<span class="line"><span>                expected_format={},</span></span>
<span class="line"><span>            ),</span></span>
<span class="line"><span>            credentials=credentials,</span></span>
<span class="line"><span>        )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        cards_posted = rsp</span></span>
<span class="line"><span>        save_cards_cache(cards_posted)</span></span>
<span class="line"><span>        yield &quot;cards_posted&quot;, cards_posted</span></span></code></pre></div><p>接下来我们按照 06 课介绍的方法，在 Linux 主机上启动 AutoGPT Server，在客户端机器上启动 AutoGPT Frontend。然后使用客户端机器的浏览器访问 Frontend 的 build 页面，创建并保存一个新的 Agent，取名为 GameDealer。如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/842359/3c3c99cbf059c7e1c61799d204b68aba.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/842359/3c3c99cbf059c7e1c61799d204b68aba.png" alt="图片"></a></p><p>注意：在点击保存按钮之前，在 Deal Cards 框中需要打开 Advanced 选项，然后在 LLM Model 下拉框中选择 Qwen2.5。配置方法与上节课介绍 AIConversationBlock 的使用时完全一样。</p><p>保存成功后，点击 build 页面中的 Run 按钮，测试 GameDealer 工作是否正常。</p><h2 id="实现并测试-mathprodigy" tabindex="-1">实现并测试 MathProdigy <a class="header-anchor" href="#实现并测试-mathprodigy" aria-label="Permalink to &quot;实现并测试 MathProdigy&quot;">​</a></h2><p>在 MathProdigy 这个 Agent 中，我们需要移植 MetaGPT 实现中的 MachineGiveExpression。我创建了一个对应的 MachineGiveExpressionBlock，以下是其 run() 函数的实现。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    def run(self, input_data: Input, **kwargs) -&amp;gt; BlockOutput:</span></span>
<span class="line"><span>        last_cards_posted = get_last_cards_posted()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        if last_cards_posted == &quot;&quot;:</span></span>
<span class="line"><span>            yield &quot;expression&quot;, &quot;expression not found&quot;</span></span>
<span class="line"><span>        else:</span></span>
<span class="line"><span>            point_list = json.loads(last_cards_posted)</span></span>
<span class="line"><span>            expressions = get_cached_expressions(point_list)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            result = &quot;expression not found&quot;</span></span>
<span class="line"><span>            if len(expressions) &amp;gt; 0:</span></span>
<span class="line"><span>                random_idx = random.randint(0, len(expressions)-1)</span></span>
<span class="line"><span>                result = expressions[random_idx]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            yield &quot;expression&quot;, result</span></span></code></pre></div><p>然后使用客户端机器的浏览器访问 Frontend 的 build 页面，创建并保存一个新的 Agent，取名为 MathProdigy。如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/842359/09a630572bd5681355852bed11092d1b.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/842359/09a630572bd5681355852bed11092d1b.png" alt="图片"></a></p><p>保存成功后，点击 build 页面中的 Run 按钮，测试 MathProdigy 工作是否正常。</p><h2 id="实现并测试-gamejudger" tabindex="-1">实现并测试 GameJudger <a class="header-anchor" href="#实现并测试-gamejudger" aria-label="Permalink to &quot;实现并测试 GameJudger&quot;">​</a></h2><p>在 GameJudger 这个 Agent 中，我们需要移植 MetaGPT 实现中的 CheckExpression。我创建了一个 CheckExpressionBlock，这个类是 AIConversationBlock 的子类。以下是其 run() 函数的实现。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    def run(</span></span>
<span class="line"><span>        self, input_data: Input, *, credentials: APIKeyCredentials, **kwargs</span></span>
<span class="line"><span>    ) -&amp;gt; BlockOutput:</span></span>
<span class="line"><span>        last_cards_posted = get_last_cards_posted()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        expression = input_data.expression</span></span>
<span class="line"><span>        if expression == &quot;expression not found&quot;:</span></span>
<span class="line"><span>            yield &quot;check_result&quot;, &quot;Correct&quot;</span></span>
<span class="line"><span>            yield &quot;last_cards_posted&quot;, last_cards_posted</span></span>
<span class="line"><span>        else:</span></span>
<span class="line"><span>            prompt = self.PROMPT_TEMPLATE.format(expression=expression)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            msg_list = [ {&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: prompt} ]</span></span>
<span class="line"><span>            rsp = self.llm_call(</span></span>
<span class="line"><span>                AIStructuredResponseGeneratorBlock.Input(</span></span>
<span class="line"><span>                    prompt=&quot;&quot;,</span></span>
<span class="line"><span>                    credentials=input_data.credentials,</span></span>
<span class="line"><span>                    model=input_data.model,</span></span>
<span class="line"><span>                    conversation_history=msg_list,</span></span>
<span class="line"><span>                    max_tokens=input_data.max_tokens,</span></span>
<span class="line"><span>                    expected_format={},</span></span>
<span class="line"><span>                ),</span></span>
<span class="line"><span>                credentials=credentials,</span></span>
<span class="line"><span>            )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            check_result = extract_result(rsp)</span></span>
<span class="line"><span>            yield &quot;check_result&quot;, check_result</span></span>
<span class="line"><span>            yield &quot;last_cards_posted&quot;, last_cards_posted</span></span></code></pre></div><p>然后使用客户端机器的浏览器访问 Frontend 的 build 页面，创建并保存一个新的 Agent，取名为 GameJudger。如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/842359/6e1d3700accec7a7fe4e01f7234db54f.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/842359/6e1d3700accec7a7fe4e01f7234db54f.png" alt="图片"></a></p><p>注意：在点击保存按钮之前，在 Check Expression 框中需要打开 Advanced 选项，然后在 LLM Model 下拉框中选择 Qwen2.5-Math。配置方法与上节课介绍 AIConversationBlock 的使用时完全一样。</p><p>与前面两个 Agent 相比， 因为增加了一个 ConditionBlock，GameJudger 显得复杂了一些。</p><p>注意一下 ConditionBlock 的用法：</p><ol><li><p>Yes Output 和 No Output 分别连接两个 AgentOutBlock，未来会通过这两个 AgentOutBlock 连接到不同的 Agent。两个 AgentOutputBlock 用不同的 name（check_correct_output、check_wrong_output）来进行区分。</p></li><li><p>将 CheckExpressionBlock 的输出项 last_cards_posted（最近发的牌）连接到 ConditionBlock 的 Yes Value 和 No Value 输入，这样做是为了将 last_cards_posted 通过 Yes Output 和 No Output 传递给两个 AgentOutputBlock，以备后续使用，下面就会看到。</p></li></ol><p>保存成功后，点击 build 页面中的 Run 按钮，测试 GameJudger 工作是否正常。</p><h2 id="实现并测试-gameplayer" tabindex="-1">实现并测试 GamePlayer <a class="header-anchor" href="#实现并测试-gameplayer" aria-label="Permalink to &quot;实现并测试 GamePlayer&quot;">​</a></h2><p>在 GamePlayer 这个 Agent 中，我们需要移植 MetaGPT 实现中的 GetHumanReply。我创建了一个 GetHumanReplyBlock，这个 Block 的 run() 函数在前面我们已经展示过了。然后使用客户端机器的浏览器访问 Frontend 的 build 页面，创建并保存一个新的 Agent，取名为 GamePlayer。如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/842359/a71bc3b6aa09d30eefc74b9144e96ff1.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/842359/a71bc3b6aa09d30eefc74b9144e96ff1.jpg" alt="图片"></a></p><p>GamePlayer 这个 Agent 最为复杂，因为在其中级联了三个 ConditionBlock。这样做的是因为用户的输入有 4 种选项：deal、help、exit 和 24 点表达式。一个 ConditionBlock 只能做两个值的比较，要区分 4 种情况，就需要级联三个 ConditionBlock。对应这 4 种情况，也有 4个 AgentOutputBlock，每个AgentOutputBlock用不同的 name 来进行区分。</p><p>保存成功后，点击 build 页面中的 Run 按钮，测试 GamePlayer 工作是否正常。</p><h2 id="实现并测试完整的游戏工作流" tabindex="-1">实现并测试完整的游戏工作流 <a class="header-anchor" href="#实现并测试完整的游戏工作流" aria-label="Permalink to &quot;实现并测试完整的游戏工作流&quot;">​</a></h2><p>在成功地分别实现了 4 个 Agent 之后，最后一步是把这 4 个 Agent 连接起来，实现完整的工作流。</p><p>最后这一步不需要实现自定义的 Block，而是完全在 Frontend 的图形界面中完成。</p><p>使用客户端机器的浏览器访问 Frontend 的 build 页面，创建并保存一个新的 Agent，取名为 24_points_game。如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/842359/072779f64de9e00526076983bdd9862c.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/842359/072779f64de9e00526076983bdd9862c.png" alt="图片"></a></p><p>实现这个完整工作流的 Agent 时，注意图中每个 Agent 不同的输入、输出节点的连接方式，确保完全按照图示中进行连接。</p><p>还要注意 GameJudger 的输出项 check_wrong_output 直接连接到 GamePlayer 的输入项 cards_posted_input。这就是前面实现 GameJudger 时，把 last_cards_posted 通过输出项 check_wrong_output 传递出来的原因。GameJudger 判断出 GamePlayer 给出的表达式错误，此时无需重新发牌，而是把上次发的牌重新传递给 GamePlayer，让 GamePlayer 重新输入。</p><p>保存成功后，点击 build 页面中的 Run 按钮，测试 24_points_game 工作是否正常。</p><p>我专门录制了一段展示视频，展示 24_points_game 成功运行的样子。这段视频略微有些卡顿，这是我故意而为，因为我为了降低课程对硬件配置的要求，故意在较低硬件配置的机器上开发和运行，包括 Linux 主机和客户端机器。</p><p>如果 24_points_game 工作正常，可喜可贺，我们基于 AutoGPT 实现的第一个 Autonomous Agent 应用——24 点游戏智能体应用就大功告成了。辛苦学习了三节课之后，我们终于收获了一个重大的成果。你真的太棒了，应该为自己自豪！喝杯咖啡庆祝一下吧。</p><p>本节课完整的自定义 Block 代码在随课程附赠的代码 my_game_blocks.py 中，其中用到的工具函数在 my_game_helpers.py 和 calc_helpers.py 中。如果你打算创建并测试自己的自定义 Block，注意为每个自定义 Block 分配一个新的全局唯一 block id，方法在上节课中已经介绍过，这里不再赘述。</p><h2 id="总结时刻" tabindex="-1">总结时刻 <a class="header-anchor" href="#总结时刻" aria-label="Permalink to &quot;总结时刻&quot;">​</a></h2><p>这节课我带你用 AutoGPT 再次实现了 04 课中 MetaGPT 实现的 24 点游戏智能体应用。在实现这个应用的过程中，我们又遇到了很多挑战。大多数挑战都被我们解决了，只有唯一的一个挑战暂时无法解决，AutoGPT 新版本暂时不支持在工作流的中间节点接受用户输入。我采用了一个临时解决方案绕开了这个问题。这其实是软件开发过程中我们经常采用的策略，永远把握全局、抓大放小，不在局部的细节问题上过早花费大量精力（甚至完全卡在细节问题上面，过早追求完美）。</p><p>与字节跳动的扣子之类闭源低代码平台不同，AutoGPT 是完全开源的，其开发团队还非常友善。积极与其开发团队保持沟通，提供必要的协助，进步的速度将比闭源平台快得多。只要其核心设计和发展方向不存在问题，随着时间的推移，一切细节问题都会得到解决。</p><p>在下一课中，我们继续学习 AutoGPT 的一些更加高级和复杂的知识，并且对 AutoGPT 未来的发展方向做出展望。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>请你仔细阅读自定义 Block 的代码实现，尝试自行实现更多的 Block。</p><p>期待你的分享。如果今天的内容对你有所帮助，也期待你转发给你的同事或者朋友，大家一起学习，共同进步。我们下节课再见！</p>`,88)])])}const A=n(p,[["render",l]]);export{g as __pageData,A as default};
